function setScorelessCount(value){const minimum=Math.max(1,scorelessSelectedPlayers.size),count=Math.max(minimum,Math.min(100,Number(value)||minimum));$('scorelessCount').value=String(count);$('scorelessCountMinus').disabled=count<=minimum;$('scorelessCountPlus').disabled=count>=100;$('scorelessCountNote').textContent=scorelessSelectedPlayers.size?`기존 플레이어 ${scorelessSelectedPlayers.size}명 포함 · 나머지는 임시 이름으로 추가됩니다.`:'기존 플레이어를 선택하거나 총 인원을 정하세요.';}
