function openScorelessSetup(boardPlayers=[]){scorelessMode='';scorelessPlayers=boardPlayers.map(({winner,draw,rank,teamId,teamName,...person})=>({...person,score:null}));scorelessTeams=[];scorelessSelectedPlayers=new Set();scorelessPlayerSignature=boardPlayers.length?'board:'+boardPlayers.map(person=>person.id).join('|'):'';scorelessBoardActive=false;$('scorelessBoardPanel').hidden=true;setScorelessCount(boardPlayers.length||2);renderScorelessPlayerChoices();$('scorelessSetupGame').textContent='';showScorelessStep(boardPlayers.length?'mode':'count');show('scorelessSetupDialog');if(!boardPlayers.length)$('scorelessCountPlus').focus();}
