function renderTeamAssignments(){const box=$('teamAssignments');box.replaceChildren();for(const team of scorelessTeams){const section=node('section',undefined,'team-assignment'),input=document.createElement('input');input.type='text';input.maxLength=40;input.value=team.name;input.setAttribute('aria-label',team.name+' 이름');input.oninput=()=>{team.name=input.value;for(const player of scorelessPlayers.filter(person=>person.teamId===team.id))player.teamName=input.value;};const members=node('div',undefined,'team-member-chips');for(const player of scorelessPlayers.filter(person=>person.teamId===team.id)){const button=node('button',player.name,'team-member-chip');button.type='button';button.setAttribute('aria-label',`${player.name}, ${team.name}. 누르면 다음 팀으로 이동`);button.onclick=()=>{const index=scorelessTeams.findIndex(item=>item.id===player.teamId),next=scorelessTeams[(index+1)%scorelessTeams.length];player.teamId=next.id;player.teamName=next.name;delete player.winner;delete player.draw;renderTeamAssignments();};members.append(button);}section.append(input,members);box.append(section);}}
function prepareTeamSetup(){try{checkScorelessContext();const entry=api.getResultEntry?.(),source=(entry?.players||scorelessPlayers).map(person=>{const next={...person,score:null};delete next.winner;delete next.draw;delete next.rank;return next;});if(source.length<2)throw Error('팀전은 플레이어가 2명 이상일 때 기록할 수 있습니다.');scorelessPlayers=source;const existing=[];for(const person of source)if(/^team-[1-4]$/.test(person.teamId||'')&&person.teamName&&!existing.some(team=>team.id===person.teamId))existing.push({id:person.teamId,name:person.teamName});const count=Math.max(2,Math.min(4,source.length,existing.length||2));scorelessTeams=existing.length>=2?existing.slice(0,count):teamDefaults(count);setTeamCount(count,{redistribute:existing.length<2});showScorelessStep('team',{persist:false});}catch(error){message('scorelessSetupError',error);}}
function showScorelessBoard(mode,{navigate=true}={}){const modeLabel=mode==='win'?'개인전 승패 기록':mode==='team'?'팀전 승패 기록':mode==='rank'?'순위 기록':'협력 기록';$('scorelessBoardTitle').textContent=pendingScoreless.game?.name?pendingScoreless.game.name+' · '+pendingScoreless.date:modeLabel;$('scorelessBoardMode').textContent=mode==='coop'?modeLabel+' · 준비 중':`${modeLabel} · ${mode==='rank'?scorelessPlayers.length:0}/${mode==='team'?scorelessTeams.length:scorelessPlayers.length}`;$('scorelessBoardHint').textContent=mode==='win'?'이름을 누르면 수정·삭제할 수 있습니다. 각 플레이어의 결과를 선택하세요.':mode==='team'?'팀별 승리·무승부·패배를 선택하세요. 플레이어 이름을 누르면 수정·삭제할 수 있습니다.':mode==='rank'?'현재 위에서부터 1위입니다. 오른쪽 손잡이를 누른 채 위아래로 옮겨 순위를 바꾸세요.':'협력 기록의 상세 기능은 준비 중입니다. 기록 방식 변경으로 다른 방식을 선택할 수 있습니다.';$('scorelessBoardError').textContent='';$('scorelessBoardPanel').hidden=false;close('scorelessSetupDialog');if(navigate)location.hash='home';updateButtons();if(navigate)$('scorelessBoardPanel').focus({preventScroll:true});}
function chooseScorelessMode(mode,preparedPlayers=null){try{checkScorelessContext();const entry=api.getResultEntry?.();if(entry?.mode===mode&&!preparedPlayers){close('scorelessSetupDialog');return;}if(entry)stopScorelessBoard({preserveNames:!preparedPlayers});if(preparedPlayers)scorelessPlayers=preparedPlayers.map(person=>({...person}));if(mode!=='team')scorelessTeams=[];scorelessMode=mode;api.startResultEntry(scorelessPlayers,mode);scorelessBoardActive=true;scorelessStep='board';showScorelessBoard(mode);persistScorelessDraft('board');}catch(error){message('scorelessSetupError',error);}}
function restoreScorelessDraft(){const draft=readScorelessDraft();if(!draft)return false;try{pendingScoreless={...draft.config,source:draft.source,context:{key:key(),epoch:accountEpoch}};scorelessSelectedPlayers=new Set(draft.selected);scorelessPlayerSignature=draft.signature;scorelessPlayers=draft.players;scorelessMode=draft.mode;scorelessTeams=draft.mode==='team'?[...new Map(draft.players.map(person=>[person.teamId,{id:person.teamId,name:person.teamName}])).values()]:[];scorelessStep=draft.step;setScorelessCount(draft.count);renderScorelessPlayerChoices();$('scorelessSetupGame').textContent=pendingScoreless.game?.name?pendingScoreless.game.name+' · '+pendingScoreless.date:'';if(draft.step==='board'){scorelessBoardActive=true;api.restoreResultEntry(draft.players,draft.mode);showScorelessBoard(draft.mode,{navigate:false});persistScorelessDraft('board');}else{scorelessBoardActive=false;$('scorelessBoardPanel').hidden=true;showScorelessStep(draft.step);if(!location.hash||location.hash==='#home')show('scorelessSetupDialog');}return true;}catch{scorelessBoardActive=false;api.endResultEntry?.();pendingScoreless=null;scorelessPlayers=[];scorelessTeams=[];scorelessSelectedPlayers=new Set();scorelessPlayerSignature='';clearScorelessDraft();return false;}}
function stopScorelessBoard({preserveNames=false}={}){const entry=api.getResultEntry?.();if(preserveNames&&entry)scorelessPlayers=entry.players.map(person=>{const next={...person,score:null};delete next.winner;delete next.draw;delete next.rank;return next;});scorelessBoardActive=false;api.endResultEntry?.();$('scorelessBoardPanel').hidden=true;$('scorelessBoardError').textContent='';updateButtons();}
