$('scoreModeOption').onclick=chooseScoreMode;$('scorelessWinMode').onclick=()=>showScorelessStep('winType',{persist:false});$('scorelessSoloWinMode').onclick=()=>chooseScorelessMode('win');$('scorelessTeamWinMode').onclick=prepareTeamSetup;$('scorelessRankMode').onclick=()=>chooseScorelessMode('rank');$('scorelessCoopMode').onclick=()=>chooseScorelessMode('coop');$('scorelessModeBack').onclick=()=>showScorelessStep('count');$('scorelessWinTypeBack').onclick=()=>showScorelessStep('mode',{persist:false});$('scorelessTeamBack').onclick=()=>showScorelessStep('winType',{persist:false});$('teamCountMinus').onclick=()=>setTeamCount(Number($('teamCount').textContent)-1);$('teamCountPlus').onclick=()=>setTeamCount(Number($('teamCount').textContent)+1);$('startTeamResult').onclick=()=>{try{checkScorelessContext();if(scorelessPlayers.length<2)throw Error('팀전은 플레이어가 2명 이상이어야 합니다.');const names=scorelessTeams.map(team=>team.name.trim());if(names.some(name=>!name))throw Error('모든 팀 이름을 입력해주세요.');if(new Set(names.map(name=>name.normalize('NFKC').toLocaleLowerCase())).size!==names.length)throw Error('팀 이름은 서로 다르게 입력해주세요.');for(const team of scorelessTeams){team.name=team.name.trim();const members=scorelessPlayers.filter(person=>person.teamId===team.id);if(!members.length)throw Error('각 팀에 플레이어를 한 명 이상 배정해주세요.');for(const member of members){member.teamName=team.name;delete member.winner;delete member.draw;}}chooseScorelessMode('team',scorelessPlayers);}catch(error){message('scorelessSetupError',error);}};
