function validScorelessRanks(players){if(players.some(person=>!Number.isSafeInteger(person.rank)||person.rank<1))return false;const groups=[...new Set(players.map(person=>person.rank))].sort((a,b)=>a-b);let expected=1;for(const rank of groups){if(rank!==expected)return false;expected+=players.filter(person=>person.rank===rank).length;}return true;}
function validTeamResults(players){const teams=[...new Map(players.filter(person=>/^team-[1-4]$/.test(person.teamId||'')&&typeof person.teamName==='string'&&person.teamName.trim()).map(person=>[person.teamId,person.teamName.trim()])).entries()];if(teams.length<2||teams.length>4||players.some(person=>typeof person.teamName!=='string'||!teams.some(([id,name])=>id===person.teamId&&name===person.teamName.trim())))return false;return teams.every(([id])=>{const members=players.filter(person=>person.teamId===id);if(!members.length||members.some(person=>typeof person.winner!=='boolean'&&person.draw!==true))return false;const first=members[0];return members.every(person=>person.draw===first.draw&&person.winner===first.winner);});}
