function scorelessResultPlayers(){checkScorelessContext();const entry=api.getResultEntry?.();if(!entry||entry.mode!==scorelessMode)throw Error('결과 기록 화면을 다시 시작해주세요.');if(scorelessMode==='coop')throw Error('협력 기록의 상세 기능은 준비 중입니다.');const players=savingPlayers(entry.players.map(person=>({...person,score:null})), '');if(scorelessMode==='win'&&players.some(person=>typeof person.winner!=='boolean'&&person.draw!==true))throw Error('모든 플레이어의 승리·무승부·패배를 선택해주세요.');if(scorelessMode==='team'&&!validTeamResults(players))throw Error('모든 팀의 구성과 승리·무승부·패배를 확인해주세요.');if(scorelessMode==='rank'&&!validScorelessRanks(players))throw Error('모든 플레이어의 순위를 1위부터 빠짐없이 선택해주세요.');return players;}
